propuesta.texto_viejo:
if trozos and archivo:
    solo = []
    i = 0
    t = bloques[trozos]
    while i < len(t):
        if t[i].startswith("### `"):
            j = i + 1
            while j < len(t) and not t[j].startswith("### `"):
                j += 1
            if archivo in t[i]:
                solo += t[i:j]
            i = j
        else:
            solo.append(t[i])
            i += 1
    if solo:
        salida += solo

